exercise.solution:
model LabL05Team {
  id       Int    @id @default(autoincrement())
  name     String
  children LabL05Player[]
  @@map("lab_l05_teams")
}

model LabL05Player {
  id    Int    @id @default(autoincrement())
  title String
  teamId Int @map("team_id")
  team LabL05Team @relation(fields: [teamId], references: [id])
  @@map("lab_l05_players")
}

